  "intent": "Exercise \"flatten-array\": implement `flatten`.\n\nTake a nested array of any depth and return a fully flattened array.\n\nNote that some language tracks may include null-like values in the input array, and the way these values are represented varies by track.\nSuch values should be excluded from the flattened array.\n\nAdditionally, the input may be of a different data type and contain different types, depending on the track.\n\nCheck the test suite for details.\n\n## Example\n\ninput: `[1, [2, 6, null], [[null, [4]], 5]]`\n\noutput: `[1, 2, 6, 4, 5]`",
  "examples": [
    {
      "name": "Flatten Array > no nesting",
      "args": [
        [
          0,
          1,
          2
        ]
      ],
      "expected": [
        0,
        1,
        2
      ]
    },
    {
      "name": "Flatten Array > flattens array with just integers present",
      "args": [
        [
          1,
          [
            2,
            3,
            4,
            5,
            6,
            7
          ],
          8
        ]
      ],
      "expected": [
        1,
        2,
        3,
        4,
        5,
        6,
        7,
        8
      ]
    },
    {
      "name": "Flatten Array > 5 level nesting",
      "args": [
        [
          0,
          2,
          [
            [
              2,
              3
            ],
            8,
            100,
            4,
            [
              [
                [
                  50
                ]
              ]
            ]
          ],
          -2
        ]
      ],
      "expected": [
        0,
        2,
        2,
        3,
        8,
        100,
        4,
        50,
        -2
      ]
    }
  ]
});

// @openarc:begin flattenArray.flatten
export const flatten: FlattenFn = (input) => arc.todo("flattenArray.flatten");
// @openarc:end flattenArray.flatten

export interface Nested extends Array<number | null | undefined | Nested> {}

export function flatten(input: Nested): number[] {
  return input.reduce((acc, item) => {
    if (Array.isArray(item)) {
      return acc.concat(flatten(item));
    } else if (item !== null && item !== undefined) {
      acc.push(item);
    }
    return acc;
  }, []);
}

