import * as arc from "open-arc";

export type AnnotateFn = (field: string[]) => string[];

export const annotateSpec = arc.defineRegion<AnnotateFn>({
  "id": "minesweeper.annotate",
  "intent": "Exercise \"minesweeper\": implement `annotate`.\n\nYour task is to add the mine counts to empty squares in a completed Minesweeper board.\nThe board itself is a rectangle composed of squares that are either empty (`' '`) or a mine (`'*'`).\n\nFor each empty square, count the number of mines adjacent to it (horizontally, vertically, diagonally).\nIf the empty square has no adjacent mines, leave it empty.\nOtherwise replace it with the adjacent mines count.\n\nFor example, you may receive a 5 x 4 board like this (empty spaces are represented here with the '·' character for display on screen):\n\n```text\n·*·*·\n··*··\n··*··\n·····\n```\n\nWhich your code should transform into this:\n\n```text\n1*3*1\n13*31\n·2*2·\n·111·\n```",
  "examples": [
    {
      "name": "Minesweeper annotate > handles no rows",
      "args": [
        []
      ],
      "expected": []
    },
    {
      "name": "Minesweeper annotate > handles no columns",
      "args": [
        [
          ""
        ]
      ],
      "expected": [
        ""
      ]
    },
    {
      "name": "Minesweeper annotate > handles no mines",
      "args": [
        [
          "   ",
          "   ",
          "   "
        ]
      ],
      "expected": [
        "   ",
        "   ",
        "   "
      ]
    }
  ]
});

// @openarc:begin minesweeper.annotate
export const annotate: AnnotateFn = (field) => arc.todo("minesweeper.annotate");
// @openarc:end minesweeper.annotate

export function annotate(field: string[]): string[] {
  const rows = field.length;
  const cols = field[0].length;
  const result: string[] = [];

  for (let i = 0; i < rows; i++) {
    const row = field[i];
    const newRow: string[] = [];
    for (let j = 0; j < cols; j++) {
      if (row[j] === ' ') {
        let count = 0;
        for (let x = -1; x <= 1; x++) {
          for (let y = -1; y <= 1; y++) {
            if (x === 0 && y === 0) continue;
            const newX = i + x;
            const newY = j + y;
            if (newX >= 0 && newX < rows && newY >= 0 && newY < cols && row[newY] === '*') {
              count++;
            }
          }
        }
        newRow.push(count.toString());
      } else {
        newRow.push(row[j]);
      }
    }
    result.push(newRow.join(''));
  }

  return result;
}

import * as arc from "open-arc";

export type CleanFn = (input: string) => string;

export const cleanSpec = arc.defineRegion<CleanFn>({
  "id": "phoneNumber.clean",
  "intent": "Exercise "phone-number": implement `clean`.

Clean up phone numbers so that they can be sent SMS messages.

The **North American Numbering Plan (NANP)** is a telephone numbering system used by many countries in North America like the United States, Canada or Bermuda.
All NANP-countries share the same international country code: `1`.

NANP numbers are ten-digit numbers consisting of a three-digit Numbering Plan Area code, commonly known as _area code_, followed by a seven-digit local number.
The first three digits of the local number represent the _exchange code_, followed by the unique four-digit number which is the _subscriber number_.

The format is usually represented as

```text
NXX NXX-XXXX
```

where `N` is any digit from 2 through 9 and `X` is any digit from 0 through 9.

Sometimes they also have the country code (represented as `1` or `+1`) prefixed.

Your task is to clean up differently formatted telephone numbers by removing punctuation and the country code if present.

For example, the inputs

- `+1 (613)-995-0253`
- `613-995-0253`
- `1 613 995 0253`
- `613.995.0253`

should all produce the output

`6139950253`

**Note:** As this exercise only deals with telephone numbers used in NANP-countries, only 1 is considered a valid country code.",
  "examples": [
    {
      "name": "Phone Number > Cleanup user-entered phone numbers > cleans the number",
      "args": [
        "(223) 456-7890"
      ],
      "expected": "2234567890"
    },
    {
      "name": "Phone Number > Cleanup user-entered phone numbers > cleans numbers with dots",
      "args": [
        "223.456.7890"
      ],
      "expected": "2234567890"
    }
  ]
});

// @openarc:begin phoneNumber.clean
export const clean: CleanFn = (input) => {
  return input.replace(/[^0-9]/g, '').replace(/^1/, '');
};
// @openarc:end phoneNumber.clean

export function clean(input: string): string {
  // Remove any non-digit characters
  const cleanedInput = input.replace(/\D/g, '');

  // Remove the country code if present
  if (cleanedInput.startsWith('1')) {
    cleanedInput = cleanedInput.slice(1);
  }

  return cleanedInput;
}

import * as arc from "open-arc";

export type TranslateFn = (phrase: string) => string;

export const translateSpec = arc.defineRegion<TranslateFn>({
  "id": "pigLatin.translate",
  "intent": "Exercise "pig-latin": implement `translate`.

Your task is to translate text from English to Pig Latin.
The translation is defined using four rules, which look at the pattern of vowels and consonants at the beginning of a word.
These rules look at each word's use of vowels and consonants:

- vowels: the letters `a`, `e`, `i`, `o`, and `u`
- consonants: the other 21 letters of the English alphabet

## Rule 1

If a word begins with a vowel, or starts with `"xr"` or `"yt"`, add an `"ay"` sound to the end of the word.

For example:

- `"apple"` -> `"appleay"` (starts with vowel)
- `"xray"` -> `"xrayay"` (starts with `"xr"`)
- `"yttria"` -> `"yttriaay"` (starts with `"yt"`)

## Rule 2

If a word begins with one or more consonants, first move those consonants to the end of the word and then add an `"ay"` sound to the end of the word.

For example:

- `"pig"` -> `"igp"` -> `"igpay"` (starts with single consonant)
- `"chair"` -> `"airch"` -> `"airchay"` (starts with multiple consonants)
- `"thrush"` -> `"ushthr"` -> `"ushthray"` (starts with multiple consonants)

## Rule 3

If a word starts with zero or more consonants followed by `"qu"`, first move those consonants (if any) and the `"qu"` part to the end of the word, and then add an `"ay"` sound to the end of the word.

For example:

- `"quick"` -> `"ickqu"` -> `"ickquay"` (starts with `"qu"`, no preceding consonants)
- `"square"` -> `"aresqu"` -> `"aresquay"` (starts with one consonant followed by `"qu`")

## Rule 4

If a word starts with one or more consonants followed by `"y"`, first move the consonants preceding the `"y"`to the end of the word, and then add an `"ay"` sound to the end of the word.

Some examples:

- `"my"` -> `"ym"` -> `"ymay"` (starts with single consonant followed by `"y"`)
- `"rhythm"` -> `"ythmrh"` -> `"ythmrhay"` (starts with multiple consonants followed by `"y"`)",
  "examples": [
    {
      "name": "ay is added to words that start with vowels > word beginning with a",
      "args": [
        "apple"
      ],
      "expected": "appleay"
    },
    {
      "name": "ay is added to words that start with vowels > word beginning with e",
      "args": [
        "ear"
      ],
      "expected": "earay"
    },
    {
      "name": "ay is added to words that start with vowels > word beginning with i",
      "args": [
        "igloo"
      ],
      "expected": "iglooay"
    }
  ]
});

// @openarc:begin pigLatin.translate
export const translate: TranslateFn = (phrase) => arc.todo("pigLatin.translate");
// @openarc:end pigLatin.translate

export function translate(phrase: string): string {
  const vowels = 'aeiou';
  const consonants = 'bcdfghjklmnpqrstvwxyz';
  const specialWords = ['xr', 'yt'];

  return phrase.split(' ').map(word => {
    if (specialWords.includes(word)) {
      return word + 'ay';
    }

    if (vowels.includes(word[0])) {
      return word + 'ay';
    }

    let consonantsPart = '';
    for (let i = 0; i < word.length; i++) {
      if (!consonants.includes(word[i])) {
        break;
      }
      consonantsPart += word[i];
    }

    if (consonantsPart) {
      return consonantsPart + word.slice(consonantsPart.length) + 'ay';
    }

    return word + 'ay';
  }).join(' ');
}

import * as arc from "open-arc";

export type CountFn = (rows: string[]) => number;

export const countSpec = arc.defineRegion<CountFn>({
  "id": "rectangles.count",
  "intent": "Exercise "rectangles": implement `count`.

Count the rectangles in an ASCII diagram like the one below.

```text
