export function transpose(rows: string[]): string[] {
  if (rows.length === 0) return [];

  const maxLength = Math.max(...rows.map(row => row.length));
  const transposed = rows.map(row => row.padStart(maxLength, ' '));

  return transposed.map((row, colIndex) => row.split('').map((char, rowIndex) => transposed[rowIndex][colIndex]).join(''));
}

