// @openarc:begin acronym.parse
export const parse: ParseFn = (phrase) => arc.todo("acronym.parse");
// @openarc:end acronym.parse

export function parse(phrase: string): string {
  // Remove punctuation and split the phrase into words
  const words = phrase.replace(/[^\w\s]/g, '').split(/\s+/);

  // Join the first letter of each word to form the acronym
  const acronym = words.map(word => word.charAt(0).toUpperCase()).join('');

  return acronym;
}

