        [
          ""
        ]
      ],
      "expected": [
        ""
      ]
    },
    {
      "name": "Minesweeper annotate > handles no mines",
      "args": [
        [
          "   ",
          "   ",
          "   "
        ]
      ],
      "expected": [
        "   ",
        "   ",
        "   "
      ]
    }
  ]
});

// @openarc:begin minesweeper.annotate
export const annotate: AnnotateFn = (field) => arc.todo("minesweeper.annotate");
// @openarc:end minesweeper.annotate

export function annotate(field: string[]): string[] {
  const rows = field.length;
  const cols = field[0].length;
  const result: string[] = [];

  for (let i = 0; i < rows; i++) {
    const row = field[i];
    const newRow: string[] = [];
    for (let j = 0; j < cols; j++) {
      if (row[j] === ' ') {
        let count = 0;
        for (let x = -1; x <= 1; x++) {
          for (let y = -1; y <= 1; y++) {
            if (x === 0 && y === 0) continue;
            const newX = i + x;
            const newY = j + y;
            if (newX >= 0 && newX < rows && newY >= 0 && newY < cols && row[newY] === '*') {
              count++;
            }
          }
        }
        newRow.push(count.toString());
      } else {
        newRow.push(row[j]);
      }
    }
    result.push(newRow.join(''));
  }

  return result;
}

