  "examples": [
    {
      "name": "Spiral Matrix > empty spiral",
      "args": [
        0
      ],
      "expected": []
    },
    {
      "name": "Spiral Matrix > trivial spiral",
      "args": [
        1
      ],
      "expected": [
        [
          1
        ]
      ]
    }
  ]
});

// @openarc:begin spiralMatrix.ofSize
export const ofSize: OfSizeFn = (size) => {
  const matrix = Array.from({ length: size }, () => Array.from({ length: size }, () => 0));
  let num = 1;
  let top = 0;
  let bottom = size - 1;
  let left = 0;
  let right = size - 1;
  while (num <= size * size) {
      for (let i = left; i <= right; i++) {
        matrix[top][i] = num;
        num++;
      }
      top++;

      for (let i = top; i <= bottom; i++) {
        matrix[i][right] = num;
        num++;
      }
      right--;

      if (top <= bottom) {
        for (let i = right; i >= left; i--) {
          matrix[bottom][i] = num;
          num++;
        }
        bottom--;
      }

      if (left <= right) {
        for (let i = bottom; i >= top; i--) {
          matrix[i][left] = num;
          num++;
        }
        left++;
      }
    }
  return matrix;
};
// @openarc:end spiralMatrix.ofSize

export function ofSize(size: number): number[][] {
  if (size <= 0) return [];

  const matrix = Array.from({ length: size }, () => Array(size).fill(0));
  let num = 1;
  let top = 0;
  let bottom = size - 1;
  let left = 0;
  let right = size - 1;

  while (num <= size * size) {
    // Fill top row
    for (let i = left; i <= right; i++) {
      matrix[top][i] = num++;
    }
    top++;

    // Fill right column
    for (let i = top; i <= bottom; i++) {
      matrix[i][right] = num++;
    }
    right--;

    // Fill bottom row
    if (top <= bottom) {
      for (let i = right; i >= left; i--) {
        matrix[bottom][i] = num++;
      }
      bottom--;
    }

    // Fill left column
    if (left <= right) {
      for (let i = bottom; i >= top; i--) {
        matrix[i][left] = num++;
      }
      left++;
    }
  }

  return matrix;
}

