// @openarc:begin variableLengthQuantity.decode
export const decode: DecodeFn = (bytes) => arc.todo("variableLengthQuantity.decode");
// @openarc:end variableLengthQuantity.decode

export function encode(numbers: number[]): number[] {
  const encodedBytes: number[] = [];
  for (const number of numbers) {
    if (number < 0) {
      throw new Error("Number must be non-negative");
    }
    if (number > 0x7F) {
      throw new Error("Number must be less than or equal to 127");
    }
    encodedBytes.push(number);
  }
  return encodedBytes;
}

export function decode(bytes: number[]): number[] {
  const decodedNumbers: number[] = [];
  for (let i = 0; i < bytes.length; i++) {
    let number = bytes[i];
    while (number > 0) {
      decodedNumbers.push(number & 0x7F);
      number >>= 7;
    }
  }
  return decodedNumbers;
}

export function answer(question: string): number {
  const regex = /^What is (\d+) (\w+) (\d+)?$/;
  const match = question.match(regex);

  if (!match) {
    throw new Error("Unsupported operations");
  }

  const num1 = parseInt(match[1], 10);
  const operator = match[2];
  const num2 = parseInt(match[3] || '0', 10);

  switch (operator) {
    case 'plus':
      return num1 + num2;
    case 'minus':
      return num1 - num2;
    case 'multiplied by':
      return num1 * num2;
    case 'divided by':
      return num1 / num2;
    default:
      throw new Error("Unsupported operations");
  }
}

