// @openarc:begin allYourBase.convert
export const convert: ConvertFn = (digits, inputBase, outputBase) => arc.todo("allYourBase.convert");
// @openarc:end allYourBase.convert

export function convert(digits: number[], inputBase: number, outputBase: number): number[] {
  let result = 0;
  for (let i = 0; i < digits.length; i++) {
    result += digits[i] * Math.pow(inputBase, digits.length - 1 - i);
  }
  return result.toString(outputBase).split('').map(Number);
}

