// @openarc:begin binarySearch.find
export const find: FindFn = (haystack, needle) => {
  let left = 0;
  let right = haystack.length - 1;
  while (left <= right) {
      const mid = Math.floor((left + right) / 2);

      if (haystack[mid] === needle) {
        return mid;
      } else if (haystack[mid] < needle) {
        left = mid + 1;
      } else {
        right = mid - 1;
      }
    }
  return -1;
};
// @openarc:end binarySearch.find

export function find(haystack: number[], needle: number): number {
  let left = 0;
  let right = haystack.length - 1;

  while (left <= right) {
    const mid = Math.floor((left + right) / 2);
    if (haystack[mid] === needle) {
      return mid;
    } else if (haystack[mid] < needle) {
      left = mid + 1;
    } else {
      right = mid - 1;
    }
  }

  return -1;
}

export function makeDiamond(character: string): string {
  if (character.length !== 1) {
    throw new Error("Input must be a single character");
  }

  const char = character.toUpperCase();
  const size = 2 * char.charCodeAt(0) - 1;
  const halfSize = size / 2;

  let result = '';

  for (let i = 0; i < halfSize; i++) {
    result += ' '.repeat(halfSize - i - 1) + char + ' '.repeat(i * 2) + char + '\n';
  }

  result += char + '\n';

  for (let i = halfSize - 2; i >= 0; i--) {
    result += ' '.repeat(halfSize - i - 1) + char + ' '.repeat(i * 2) + char + '\n';
  }

  return result;
}

