export function verse(n: number): string {
  const words = [
    "fly",
    "spider",
    "bird",
    "cat",
    "dog",
    "goat",
    "cow",
    "horse"
  ];

  const verseText = `I know an old lady who swallowed a ${words[n - 1]}.`;
  if (n > 1) {
    verseText += `\nIt wriggled and jiggled and tickled inside her.`;
  }
  verseText += `\nShe swallowed the ${words[n - 1]} to catch the ${words[n - 2]}.`;
  if (n > 2) {
    verseText += `\nI don't know why she swallowed the ${words[n - 1]}. Perhaps she'll die.`;
  }

  return verseText;
}

export function verses(start: number, end: number): string {
  let result = "";
  for (let i = start; i <= end; i++) {
    result += verse(i) + "\n\n";
  }
  return result.trim();
}

