export const count: CountFn = (rows) => {
  if (!rows || rows.length === 0) return 0;
  if (rows.length === 1) return 0;
  let count = 0;
  for (let i = 0; i < rows.length - 1; i++) {
      for (let j = 0; j < rows[0].length - 1; j++) {
        if (rows[i][j] === '+' && rows[i][j + 1] === '+' && rows[i + 1][j] === '+' && rows[i + 1][j + 1] === '+') {
          count++;
        }
      }
    }
  return count;
};
