export const find: FindFn = (haystack, needle) => {
  if (needle < haystack[0] || needle > haystack[haystack.length - 1]) return -1;
    let left = 0;
    let right = haystack.length - 1;
    while (left <= right) {
      const mid = left + ((right - left) >> 1);
      if (haystack[mid] === needle) return mid;
      if (haystack[mid] < needle) {
        left = mid + 1;
      } else {
        right = mid - 1;
      }
    }
    return -1;
};
