// @openarc:begin flattenArray.flatten
export const flatten: FlattenFn = (input) => {
  const flat = (arr: any[]): number[] => {
    return arr.reduce((acc: number[], val: any) => {
      if (Array.isArray(val)) {
        return acc.concat(flat(val));
      }
      if (val !== null && val !== undefined) {
        acc.push(val);
      }
      return acc;
    }, []);
  };
  return flat(input);
};
