          5
        ],
        4
      ],
      "expected": 3
    },
    {
      "name": "Sum Of Multiples > more than one multiple within limit",
      "args": [
        [
          3
        ],
        7
      ],
      "expected": 9
    }
  ]
});

// @openarc:begin sumOfMultiples.sum
export const sum: SumFn = (factors, limit) => arc.todo("sumOfMultiples.sum");
// @openarc:end sumOfMultiples.sum

{
  "sum": function(factors: number[], limit: number): number {
    const uniqueMultiples = new Set<number>();
    for (const factor of factors) {
      for (let i = factor; i < limit; i += factor) {
        uniqueMultiples.add(i);
      }
    }
    return Array.from(uniqueMultiples).reduce((acc, val) => acc + val, 0);
  }
}

