// @openarc:begin allYourBase.convert
export const convert: ConvertFn = (digits, inputBase, outputBase) => {
  if (inputBase === outputBase) return digits;
    const result = [];
    let temp = 0;
    for (let i = 0; i < digits.length; i++) {
      temp = temp * inputBase + digits[i];
    }
    while (temp > 0) {
      result.push(temp % outputBase);
      temp = Math.floor(temp / outputBase);
    }
    return result.reverse();
};
// @openarc:end allYourBase.convert

{
  "convert": function(digits, inputBase, outputBase) {
    if (inputBase < 2 || outputBase < 2) {
      throw new Error("Both input and output bases must be at least 2.");
    }

    let result = 0;
    for (let i = 0; i < digits.length; i++) {
      result += digits[i] * Math.pow(inputBase, digits.length - 1 - i);
    }

    if (result === 0) {
      return [0];
    }

    let output = [];
    while (result > 0) {
      output.push(Math.floor(result % outputBase));
      result = Math.floor(result / outputBase);
    }

    return output.reverse();
  }
}

