import * as arc from "open-arc";

export type TranslateFn = (phrase: string) => string;

export const translateSpec = arc.defineRegion<TranslateFn>({
  "id": "pigLatin.translate",
  "intent": "Exercise "pig-latin": implement `translate`.

Your task is to translate text from English to Pig Latin.
The translation is defined using four rules, which look at the pattern of vowels and consonants at the beginning of a word.
These rules look at each word's use of vowels and consonants:

- vowels: the letters `a`, `e`, `i`, `o`, and `u`
- consonants: the other 21 letters of the English alphabet

## Rule 1

If a word begins with a vowel, or starts with `"xr"` or `"yt"`, add an `"ay"` sound to the end of the word.

For example:

- `"apple"` -> `"appleay"` (starts with vowel)
- `"xray"` -> `"xrayay"` (starts with `"xr"`)
- `"yttria"` -> `"yttriaay"` (starts with `"yt"`)

## Rule 2

If a word begins with one or more consonants, first move those consonants to the end of the word and then add an `"ay"` sound to the end of the word.

For example:

- `"pig"` -> `"igp"` -> `"igpay"` (starts with single consonant)
- `"chair"` -> `"airch"` -> `"airchay"` (starts with multiple consonants)
- `"thrush"` -> `"ushthr"` -> `"ushthray"` (starts with multiple consonants)

## Rule 3

If a word starts with zero or more consonants followed by `"qu"`, first move those consonants (if any) and the `"qu"` part to the end of the word, and then add an `"ay"` sound to the end of the word.

For example:

- `"quick"` -> `"ickqu"` -> `"ickquay"` (starts with `"qu"`, no preceding consonants)
- `"square"` -> `"aresqu"` -> `"aresquay"` (starts with one consonant followed by `"qu`")

## Rule 4

If a word starts with one or more consonants followed by `"y"`, first move the consonants preceding the `"y"`to the end of the word, and then add an `"ay"` sound to the end of the word.

Some examples:

- `"my"` -> `"ym"` -> `"ymay"` (starts with single consonant followed by `"y"`)
- `"rhythm"` -> `"ythmrh"` -> `"ythmrhay"` (starts with multiple consonants followed by `"y"`)",
  "examples": [
    {
      "name": "ay is added to words that start with vowels > word beginning with a",
      "args": [
        "apple"
      ],
      "expected": "appleay"
    },
    {
      "name": "ay is added to words that start with vowels > word beginning with e",
      "args": [
        "ear"
      ],
      "expected": "earay"
    },
    {
      "name": "ay is added to words that start with vowels > word beginning with i",
      "args": [
        "igloo"
      ],
      "expected": "iglooay"
    }
  ]
});

// @openarc:begin pigLatin.translate
export const translate: TranslateFn = (phrase) => {
  if (phrase === '') return ''; const vowels = 'aeiouAEIOU'; const qu = 'qu'; const y = 'y'; const xr = 'xr'; const yt = 'yt'; const words = phrase.split(' '); const result = []; for (const word of words) { if (vowels.includes(word[0])) { result.push(word + 'ay'); } else if (word.startsWith(xr) || word.startsWith(yt)) { result.push(word + 'ay'); } else if (word.startsWith(qu)) { const match = word.match(/(.*?)(qu)/); if (match) { result.push(match[1] + 'qu' + 'ay'); } } else if (word.startsWith(y)) { const match = word.match(/(.*?)(y)/); if (match) { result.push(match[1] + 'y' + 'ay'); } } else { const match = word.match(/(.*?)([^aeiouAEIOU])/); if (match) { result.push(match[1] + match[2] + 'ay'); } } } return result.join(' ');
};
// @openarc:end pigLatin.translate

{
  "translate": function(phrase: string): string {
    const vowels = "aeiouAEIOU";
    const consonants = "bcdfghjklmnpqrstvwxyzBCDFGHJKLMNPQRSTVWXYZ";
    const special = "xr yt";

    const words = phrase.split(" ");
    const result: string[] = [];

    for (const word of words) {
      if (word === "") continue;

      if (special.includes(word[0])) {
        result.push(word.slice(2) + word[0] + "ay");
      } else if (vowels.includes(word[0])) {
        result.push(word + "ay");
      } else {
        let consonantsPart = "";
        let i = 0;
        while (i < word.length && !vowels.includes(word[i])) {
          consonantsPart += word[i];
          i++;
        }
        if (consonantsPart === "") {
          result.push(word + "ay");
        } else {
          result.push(word.slice(i) + consonantsPart + "ay");
        }
      }
    }

    return result.join(" ");
  }
}

