import * as arc from "open-arc";

export type SumFn = (factors: number[], limit: number) => number;

export const sumSpec = arc.defineRegion<SumFn>({
  "id": "sumOfMultiples.sum",
  "intent": "Exercise \"sum-of-multiples\": implement `sum`.\n\nYour task is to write the code that calculates the energy points that get awarded to players when they complete a level.\n\nThe points awarded depend on two things:\n\n- The level (a number) that the player completed.\n- The base value of each magical item collected by the player during that level.\n\nThe energy points are awarded according to the following rules:\n\n1. For each magical item, take the base value and find all the multiples of that value that are less than the level number.\n2. Combine the sets of numbers.\n3. Remove any duplicates.\n4. Calculate the sum of all the numbers that are left.\n\nLet's look at an example:\n\n**The player completed level 20 and found two magical items with base values of 3 and 5.**\n\nTo calculate the energy points earned by the player, we need to find all the unique multiples of these base values that are less than level 20.\n\n- Multiples of 3 less than 20: `{3, 6, 9, 12, 15, 18}`\n- Multiples of 5 less than 20: `{5, 10, 15}`\n- Combine the sets and remove duplicates: `{3, 5, 6, 9, 10, 12, 15, 18}`\n- Sum the unique multiples: `3 + 5 + 6 + 9 + 10 + 12 + 15 + 18 = 78`\n- Therefore, the player earns **78** energy points for completing level 20 and finding the two magical items with base values of 3 and 5.",
  "examples": [
    {
      "name": "Sum Of Multiples > no multiples within limit",
      "args": [
        [
          3,
          5
        ],
        1
      ],
      "expected": 0
    },
    {
      "name": "Sum Of Multiples > one factor has multiples within limit",
      "args": [
        [
          3,
          5
        ],
        4
      ],
      "expected": 3
    },
    {
      "name": "Sum Of Multiples > more than one multiple within limit",
      "args": [
        [
          3
        ],
        7
      ],
      "expected": 9
    }
  ]
});

// @openarc:begin sumOfMultiples.sum
export const sum: SumFn = (factors, limit) => arc.todo("sumOfMultiples.sum");
// @openarc:end sumOfMultiples.sum

{
  "sum": function(factors: number[], limit: number): number {
    const uniqueMultiples = new Set<number>();
    for (const factor of factors) {
      for (let i = factor; i < limit; i += factor) {
        uniqueMultiples.add(i);
      }
    }
    return Array.from(uniqueMultiples).reduce((acc, val) => acc + val, 0);
  }
}

import * as arc from "open-arc";

export type TransposeFn = (rows: string[]) => string[];

export const transposeSpec = arc.defineRegion<TransposeFn>({
  "id": "transpose.transpose",
  "intent": "Exercise "transpose": implement `transpose`.

Given an input text output it transposed.

Roughly explained, the transpose of a matrix:

```text
ABC
DEF
```

is given by:

```text
AD
BE
CF
```

Rows become columns and columns become rows.
See [transpose][].

If the input has rows of different lengths, this is to be solved as follows:

- Pad to the left with spaces.
- Don't pad to the right.

Therefore, transposing this matrix:

```text
ABC
DE
```

results in:

```text
AD
BE
C
```

And transposing:

```text
AB
DEF
```

results in:

```text
AD
BE
 F
```

In general, all characters from the input should also be present in the transposed output.
That means that if a column in the input text contains only spaces on its bottom-most row(s), the corresponding output row should contain the spaces in its right-most column(s).

[transpose]: https://en.wikipedia.org/wiki/Transpose",
  "examples": [
    {
      "name": "Transpose > empty string",
      "args": [
        []
      ],
      "expected": []
    },
    {
      "name": "Transpose > two characters in a row",
      "args": [
        [
          "A1"
        ]
      ],
      "expected": [
        "A",
        "1"
      ]
    },
    {
      "name": "Transpose > two characters in a column",
      "args": [
        [
          "A",
          "1"
        ]
      ],
      "expected": [
        "A1"
      ]
    }
  ]
});

// @openarc:begin transpose.transpose
export const transpose: TransposeFn = (rows) => {
  const maxLen = Math.max(...rows.map(r => r.length));
  const transposed: string[] = [];
  for (let i = 0; i < maxLen; i++) {
    let row = '';
    for (let j = 0; j < rows.length; j++) {
      const char = rows[j][i] || ' ';
      row += char;
    }
    transposed.push(row);
  }
  return transposed;
};
// @openarc:end transpose.transpose

{
  "transpose": function(rows: string[]): string[] {
    if (rows.length === 0) return [];
    const maxLen = Math.max(...rows.map(row => row.length));
    const transposed: string[] = [];
    for (let i = 0; i < maxLen; i++) {
      let col = "";
      for (let j = 0; j < rows.length; j++) {
        if (i < rows[j].length) {
          col += rows[j][i];
        }
      }
      transposed.push(col);
    }
    return transposed;
  }
}

