{
  "answer": function(question: string): number {
    const match = question.match(/What is (\d+) (\w+) (\d+)/);
    if (!match) return NaN;

    const num1 = parseInt(match[1], 10);
    const op = match[2];
    const num2 = parseInt(match[3], 10);

    switch (op) {
      case "plus":
        return num1 + num2;
      case "minus":
        return num1 - num2;
      case "multiplied by":
        return num1 * num2;
      case "divided by":
        return num1 / num2;
      default:
        return NaN;
    }
  }
}
